style.css:
/* Background */
body {
    background-color: #fff0f6 !important; /* very soft pink */
}

/* Main containers */
div, section {
    background-color: #fff5fa !important;
    border-radius: 12px !important;
}

/* Header bar */
header {
    background-color: #ffd6e7 !important;
    box-shadow: none !important;
}

/* Buttons */
button {
    background-color: #ffb6d9 !important;
    color: white !important;
    border-radius: 999px !important;
    border: none !important;
}

/* Button hover */
button:hover {
    background-color: #ff9fcd !important;
}

/* Search bar */
input {
    background-color: #ffe4f0 !important;
    border-radius: 999px !important;
    border: none !important;
}

/* Links */
a {
    color: #ff7eb6 !important;
}

/* Pins hover effect */
div:hover {
    transform: scale(1.01);
    transition: 0.2s ease;
}

/* Scrollbar (cute detail) */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-track {
    background: #fff0f6;
}

::-webkit-scrollbar-thumb {
    background: #ffb6d9;
    border-radius: 10px;
}
